import{_ as t,l,o as e,c as s,v as i,p as n,x as o,d as c,i as d,S as p}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"kABI 与模块签名","description":"","frontmatter":{"title":"kABI 与模块签名","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kabi-module-signing.md","filePath":"cs/kabi-module-signing.md","lastUpdated":1789023840000}'),h={name:"cs/kabi-module-signing.md"};function u(_,a,k,m,A,B){const r=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=i('<h1 id="kabi-与模块签名" tabindex="-1">kABI 与模块签名 <a class="header-anchor" href="#kabi-与模块签名" aria-label="Permalink to &quot;kABI 与模块签名&quot;">​</a></h1><div class="epigraph"><p>发行版冻结一组内核符号的 ABI，使闭源或 DKMS 模块可在更新间加载；模块签名让 [Secure Boot](/cs/secure-boot) 下只有可信模块能进核。</p><footer>—— 据 Linux 模块签名文档；发行版 kABI 白皮书直觉；[livepatch](/cs/livepatch) 为替换对照</footer></div><p><a href="/cs/kernel-config-build">配置</a> 产出模块。缺口是 <strong>能不能加载</strong>：符号 CRC、签名、与 GPL-only 符号。观测/安全启动课序在此收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>modprobe</code> 解析未定义符号。kABI：发行版保证部分符号稳定。缺口：自己编的内核无此保证；签名：<code>CONFIG_MODULE_SIG</code>，密钥在 MOK。本课不把如何绕过签名当内容。</p><p><span class="marginnote"> vermagic 匹配配置。对象是加载策略，不是 C 调用约定课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加载：验签名 → 验 vermagic → 重定位。对照 <a href="/cs/linux-capabilities">capabilities</a>：<code>CAP_SYS_MODULE</code>。对照 livepatch：也是模块。对照 <a href="/cs/chardev-ioctl">ioctl</a>：模块常注册 cdev。</p>',8)),(e(),n(p,null,{default:o(()=>[d(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KO%5B%22.ko%22%5D%20--%3E%20SIG%5B%22%E9%AA%8C%E7%AD%BE%E5%90%8D%22%5D%0A%20%20SIG%20--%3E%20VER%5B%22vermagic%2FkABI%22%5D%0A%20%20VER%20--%3E%20REL%5B%22%E9%93%BE%E6%8E%A5%E8%BF%9B%E5%86%85%E6%A0%B8%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[c(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>kABI+签名把「内核可扩展」限制在可信与兼容的模块上，服务稳定性和安全启动。自编译内核则你就是 ABI。不要写成驱动商店。与 <a href="/cs/ebpf-observability">eBPF</a>：BPF 不走模块符号表同一套。</p><p>崩溃的模块 taint 内核，影响支持。</p><p>实现上：CRC 对符号类型变了就会拒载。Secure Boot 下未签名模块直接失败。GPL-only 符号限制专有模块能钩的深度。 读法上只引用<a href="/cs/kernel-config-build">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>kABI 与模块签名</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 GPL 符号争议。不保证 Android GKI 的细节。下一单元虚拟化：hypervisor 类型。</p><p>版本字段会变，课序钉的是机制对象「kABI 与模块签名」，不是某一主线内核的结构体名。 后课默认：模块要匹配 ABI 且可验签。第一类/第二类 hypervisor，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模块加载检查符号、vermagic、可选签名。</li><li>发行版 kABI 冻结子集以便外模块。</li><li>虚拟化类型是下一单元。</li><li>出处：module signing；kbuild；发行版 kABI。</li></ul>',11))])}const g=t(h,[["render",u]]);export{f as __pageData,g as default};
